     "t": "math",
     "tex": "y_\\alpha(t) = \\left[\\frac{dx_1(t)}{dt}\\right]^2 + \\left[\\frac{dx_2(t)}{dt}\\right]^2 + 2 \\left[\\frac{dx_1(t)}{dt}\\right]\\left[\\frac{dx_2(t)}{dt}\\right]"
